from __future__ import annotations; import json; import sys; from datetime import date; from pathlib import Path; from typing import Any; import pytest; from data_engine.datahub.production_topt.concept_mapping import DEFAULT_RULESET; from data_engine.datahub.production_topt.parser_identity import MAPPING_VERSION, PARSER_VERSION; from data_engine.datahub.production_topt.sec_financial_adapter import ( annual_values_by_period_end, build_bundle, ); from data_engine.datahub.standards import segment_extraction; from data_engine.quality import vendor_oracle; from factors.production_topt import OperatingBranch; sys.path.insert(0, str(Path(__file__).resolve().parent / "support")); from sec_route import served_financial_record; _TESTS = Path(__file__).resolve().parent; _CRWD_FIXTURE = _TESTS / "fixtures" / "sec" / "CRWD_CIK0001535527.trimmed.json"; _SAMPLES = _TESTS.parent / "samples" / "sec"; _CRWD_CIK = 1535527; _CUTOFF = date(2026, 10, 15)
_ORACLE_ONLY = { "SalesRevenueNet": "A total from before ASC 606. The ruleset leaves it out: see the sample test below.", "SalesRevenueGoodsNet": "The goods part of SalesRevenueNet. NICE and PLUG tag it last for FY2017.", "SalesRevenueServicesNet": "The services part of SalesRevenueNet. NICE, PLUG and SHOP tag it last for FY2017.", "RevenuesNetOfInterestExpense": "A bank's top line. The ruleset declares it under `bank_revenue`.", "PremiumsEarnedNet": "An insurer's earned premiums top line (#1517).", "InterestIncomeExpenseNet": "A bank's net interest income component when total revenue is untagged (#1517).", "NoninterestIncome": "A bank's noninterest income component when total revenue is untagged (#1517).", "FinancialServicesRevenue": "Financial and payment services revenue (#1517).", "HealthCareOrganizationRevenue": "Healthcare services revenue (#1517).", "OperatingLeasesIncomeStatementLeaseRevenue": "Operating lease top-line revenue (#1517).", }
def _ruleset_names(field: str) -> list[str]: mapping = DEFAULT_RULESET.mapping_for(field); assert mapping is not None, f"the ruleset declares no {field!r} field"; return [f"{item.taxonomy}:{item.concept}" for item in mapping.concepts]
def _annual(end: str, start: str, val: int, filed: str) -> dict[str, Any]: return {"start": start, "end": end, "val": val, "filed": filed, "form": "10-K", "fy": int(end[:4]), "fp": "FY"}
def test_the_deployed_route_reads_crwd_revenue_from_the_including_form(monkeypatch) -> None: outcome = served_financial_record( monkeypatch, _CRWD_FIXTURE.read_bytes(), cik=_CRWD_CIK, ticker="CRWD", cutoff_date=_CUTOFF ); assert outcome.record is not None; payload = outcome.record.payload; expected = { "revenue": "4812005000", "revenue_period_end": "2026-01-31", "gross_profit": "3593076000", "operating_period_end": "2026-01-31", "total_assets": "12025001000", "shares_outstanding": "1023934842", }; assert {key: payload[key] for key in expected} == expected; assert payload["vintage"]["revenue"]["accession"] == "0001535527-26-000010"; assert outcome.record.parser_version == PARSER_VERSION; assert outcome.record.mapping_version == f"{MAPPING_VERSION}+{DEFAULT_RULESET.content_sha256[:12]}"
@pytest.mark.parametrize( "preferred", ["RevenueFromContractWithCustomerExcludingAssessedTax", "Revenues"], )
def test_an_issuer_that_reports_two_forms_keeps_the_earlier_form(preferred: str) -> None: facts = { "facts": { "us-gaap": { preferred: {"units": {"USD": [_annual("2025-12-31", "2025-01-01", 900, "2026-02-10")]}}, "RevenueFromContractWithCustomerIncludingAssessedTax": { "units": {"USD": [_annual("2025-12-31", "2025-01-01", 950, "2026-02-10")]} }, } } }; bundle = build_bundle(facts, _CUTOFF, OperatingBranch.NON_FINANCIAL, ruleset=DEFAULT_RULESET); assert (bundle.revenue, bundle.revenue_period_end) == (900, date(2025, 12, 31)); assert bundle.vintages["revenue"]["period_end"] == "2025-12-31"
def test_the_segment_reader_tries_the_ruleset_revenue_concepts_in_order() -> None: expected = list(dict.fromkeys(_ruleset_names("revenue") + _ruleset_names("bank_revenue"))); assert list(segment_extraction._REVENUE_CONCEPTS) == expected
def test_the_vendor_oracle_differs_from_the_ruleset_only_where_stated() -> None: ruleset = _ruleset_names("revenue"); assert all(name.startswith("us-gaap:") for name in ruleset), "the oracle reads only the us-gaap taxonomy"; oracle = {f"us-gaap:{name}" for name in vendor_oracle._REVENUE_CONCEPTS}; assert [name for name in ruleset if name not in oracle] == []; assert sorted(name.removeprefix("us-gaap:") for name in oracle - set(ruleset)) == sorted(_ORACLE_ONLY); assert "us-gaap:RevenuesNetOfInterestExpense" in _ruleset_names("bank_revenue"); expected_cogs = [ n.removeprefix("us-gaap:") for n in _ruleset_names("cost_of_revenue") + _ruleset_names("insurance_claims") ]; assert list(vendor_oracle._COGS_CONCEPTS) == list(dict.fromkeys(expected_cogs)); assert "OperatingCostsAndExpenses" not in vendor_oracle._COGS_CONCEPTS; assert list(vendor_oracle._ASSETS_CONCEPTS) == [n.removeprefix("us-gaap:") for n in _ruleset_names("total_assets")]; facts = { "facts": { "us-gaap": { "Revenues": {"units": {"USD": [_annual("2025-12-31", "2025-01-01", 1000, "2026-02-10")]}}, "OperatingCostsAndExpenses": { "units": {"USD": [_annual("2025-12-31", "2025-01-01", 800, "2026-02-10")]} }, } } }; assert vendor_oracle.gross_profit(facts, _CUTOFF) is None
@pytest.mark.parametrize("sample", ["NICE_CIK0001003935.json", "PLUG_CIK0001093691.json"])
def test_sales_revenue_net_holds_only_years_that_a_later_concept_replaces(sample: str) -> None: facts = json.loads((_SAMPLES / sample).read_bytes()); legacy = annual_values_by_period_end(facts, "us-gaap", "SalesRevenueNet", "USD", _CUTOFF); bundle = build_bundle(facts, _CUTOFF, OperatingBranch.NON_FINANCIAL, ruleset=DEFAULT_RULESET); assert legacy, f"{sample} carries no annual SalesRevenueNet"; assert max(legacy) == date(2017, 12, 31); assert bundle.revenue_period_end == date(2025, 12, 31); assert bundle.vintages["revenue"]["period_end"] == "2025-12-31"
